// Command kvdebye generates zz_kvDebye_coeffs.go: the polynomials U_k of
// Debye's uniform expansion of K_v(v z) (DLMF 10.41.4), from the recurrence
// DLMF 10.41.9 in exact rational arithmetic,
//
//	U_{k+1}(p) = p^2 (1-p^2) U_k'(p) / 2 + (1/8) int_0^p (1 - 5 t^2) U_k(t) dt,
//
// U_0 = 1. U_k(p) = p^k * sum_{j=0..k} c[k][j] p^(2j); each c is the exact
// rational rounded once to float64. With -report it prints max |U_k| on [0,1]
// and the order v above which the first neglected term is below 2^-64.
//
//	go run ./testdata/gen/kvdebye > zz_kvDebye_coeffs.go
//	go run ./testdata/gen/kvdebye -report
package main

import (
	"flag"
	"fmt"
	"math"
	"math/big"
	"os"
)

const (
	kvDebyeMax = 24 // computed, for -report
	kvDebyeOut = 16 // in the table: kvDebyeTerms of kv_fast.go
)

type poly map[int]*big.Rat

func add(p poly, e int, c *big.Rat) {
	if p[e] == nil {
		p[e] = new(big.Rat)
	}
	p[e].Add(p[e], c)
}

func next(u poly) poly {
	n := poly{}
	for e, c := range u {
		if e > 0 {
			d := new(big.Rat).Mul(c, big.NewRat(int64(e), 1))
			add(n, e+1, new(big.Rat).Mul(d, big.NewRat(1, 2)))
			add(n, e+3, new(big.Rat).Mul(d, big.NewRat(-1, 2)))
		}
		add(n, e+1, new(big.Rat).Mul(c, big.NewRat(1, int64(8*(e+1)))))
		add(n, e+3, new(big.Rat).Mul(c, big.NewRat(-5, int64(8*(e+3)))))
	}
	return n
}

func main() {
	report := flag.Bool("report", false, "print the size of U_k instead of the table")
	flag.Parse()
	us := []poly{{0: big.NewRat(1, 1)}}
	for k := 0; k < kvDebyeMax; k++ {
		us = append(us, next(us[k]))
	}
	if *report {
		for k := 1; k <= kvDebyeMax; k++ {
			mx := 0.0
			for i := 0; i <= 2000; i++ {
				p := float64(i) / 2000
				s := 0.0
				for e, c := range us[k] {
					f, _ := c.Float64()
					s += f * math.Pow(p, float64(e))
				}
				mx = math.Max(mx, math.Abs(s))
			}
			fmt.Printf("k=%2d max|U_k|=%.3e  v for 2^-64: %.1f\n", k, mx, math.Pow(mx*0x1p64, 1/float64(k)))
		}
		return
	}
	w := os.Stdout
	fmt.Fprintln(w, "// Code generated by testdata/gen/kvdebye; DO NOT EDIT.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "package special")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "// kvDebyeU[k-1][j] is the coefficient of p^(k+2j) in U_k(p), the polynomials of")
	fmt.Fprintln(w, "// Debye's expansion of K_v(vz) (DLMF 10.41.4), exact rationals from the")
	fmt.Fprintln(w, "// recurrence DLMF 10.41.9 rounded once to float64.")
	fmt.Fprintf(w, "var kvDebyeU = [%d][%d]float64{\n", kvDebyeOut, kvDebyeOut+1)
	for k := 1; k <= kvDebyeOut; k++ {
		fmt.Fprint(w, "\t{")
		for j := 0; j <= k; j++ {
			c := us[k][k+2*j]
			if c == nil {
				c = new(big.Rat)
			}
			f, _ := c.Float64()
			if j > 0 {
				fmt.Fprint(w, ", ")
			}
			fmt.Fprintf(w, "%v", f)
		}
		fmt.Fprintln(w, "},")
	}
	fmt.Fprintln(w, "}")
	for k := 1; k <= kvDebyeMax; k++ {
		for e := range us[k] {
			if e < k || (e-k)%2 != 0 || e > 3*k {
				fmt.Fprintf(os.Stderr, "unexpected power %d in U_%d\n", e, k)
				os.Exit(1)
			}
		}
	}
}
